import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const generatedTypeHeader =
  "// Generated by scripts/office-v2-contracts-generate.mjs. Do not edit.";

const repositoryRoot = resolve(import.meta.dirname, "..");
const commonDescriptor = Object.freeze({
  schemaRelativePath: "docs/office-v2/schemas/common-v2.schema.json",
  generatedRelativePath: "packages/office-v2-contracts/src/generated/common-v2.ts",
  schemaId: "https://affiliate-operations.example/schemas/office-v2/common-v2.schema.json",
});

export const officeV2SchemaDescriptors = Object.freeze([
  commonDescriptor,
  Object.freeze({
    schemaRelativePath: "docs/office-v2/schemas/geometry.schema.json",
    generatedRelativePath: "packages/office-v2-contracts/src/generated/geometry.ts",
    schemaId: "https://affiliate-operations.example/schemas/office-v2/geometry.schema.json",
  }),
  Object.freeze({
    schemaRelativePath: "docs/office-v2/schemas/entity-definition-v2.schema.json",
    generatedRelativePath: "packages/office-v2-contracts/src/generated/entity-definition-v2.ts",
    schemaId: "https://affiliate-operations.example/schemas/office-v2/entity-definition-v2.schema.json",
  }),
  Object.freeze({
    schemaRelativePath: "docs/office-v2/schemas/entity-instance.schema.json",
    generatedRelativePath: "packages/office-v2-contracts/src/generated/entity-instance.ts",
    schemaId: "https://affiliate-operations.example/schemas/office-v2/entity-instance.schema.json",
  }),
  Object.freeze({
    schemaRelativePath: "docs/office-v2/schemas/definition-bundle.schema.json",
    generatedRelativePath: "packages/office-v2-contracts/src/generated/definition-bundle.ts",
    schemaId: "https://affiliate-operations.example/schemas/office-v2/definition-bundle.schema.json",
  }),
]);

function typeNameFromDefinition(name) {
  return name
    .split(/[-_]/u)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

function literal(value) {
  return JSON.stringify(value);
}

function propertyName(name) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/u.test(name) ? name : literal(name);
}

function union(values) {
  return values.length === 1 ? values[0] : values.join(" | ");
}

function shouldBrand(name) {
  return name.endsWith("Id") || name.endsWith("Reference") || name.endsWith("Position");
}

function descriptorOrder(descriptors) {
  return [...descriptors].toSorted((left, right) => (
    left.schemaRelativePath.localeCompare(right.schemaRelativePath)
    || left.generatedRelativePath.localeCompare(right.generatedRelativePath)
  ));
}

export function validateSchemaDescriptors(descriptors = officeV2SchemaDescriptors) {
  if (!Array.isArray(descriptors) || descriptors.length === 0) {
    throw new Error("contract.generator-descriptor-invalid: registry must not be empty");
  }
  const schemaPaths = new Set();
  const generatedPaths = new Set();
  const schemaIds = new Set();
  for (const descriptor of descriptors) {
    if (!descriptor || typeof descriptor !== "object") {
      throw new Error("contract.generator-descriptor-invalid: descriptor must be an object");
    }
    for (const field of ["schemaRelativePath", "generatedRelativePath", "schemaId"]) {
      if (typeof descriptor[field] !== "string" || descriptor[field].length === 0) {
        throw new Error(`contract.generator-descriptor-invalid: missing ${field}`);
      }
    }
    if (!descriptor.schemaRelativePath.endsWith(".schema.json")) {
      throw new Error(`contract.generator-descriptor-invalid: schema path ${descriptor.schemaRelativePath}`);
    }
    if (!descriptor.generatedRelativePath.endsWith(".ts")) {
      throw new Error(`contract.generator-descriptor-invalid: generated path ${descriptor.generatedRelativePath}`);
    }
    if (descriptor.schemaRelativePath.includes("..") || descriptor.generatedRelativePath.includes("..")) {
      throw new Error("contract.generator-descriptor-invalid: paths must stay inside the repository");
    }
    if (schemaPaths.has(descriptor.schemaRelativePath)) {
      throw new Error(`contract.generator-descriptor-collision: schema ${descriptor.schemaRelativePath}`);
    }
    if (generatedPaths.has(descriptor.generatedRelativePath)) {
      throw new Error(`contract.generator-descriptor-collision: output ${descriptor.generatedRelativePath}`);
    }
    if (schemaIds.has(descriptor.schemaId)) {
      throw new Error(`contract.generator-descriptor-collision: schema id ${descriptor.schemaId}`);
    }
    schemaPaths.add(descriptor.schemaRelativePath);
    generatedPaths.add(descriptor.generatedRelativePath);
    schemaIds.add(descriptor.schemaId);
  }
  return descriptorOrder(descriptors);
}

function readSchemas(root, descriptors) {
  const ordered = validateSchemaDescriptors(descriptors);
  const schemas = new Map();
  for (const descriptor of ordered) {
    const schemaPath = join(root, descriptor.schemaRelativePath);
    if (!existsSync(schemaPath)) {
      throw new Error(`contract.generator-schema-missing: ${descriptor.schemaRelativePath}`);
    }
    const bytes = readFileSync(schemaPath);
    const schema = JSON.parse(bytes.toString("utf8"));
    if (schema.$id !== descriptor.schemaId) {
      throw new Error(`contract.generator-schema-id: expected ${descriptor.schemaId}`);
    }
    schemas.set(descriptor.schemaId, { descriptor, schema, bytes });
  }
  return { ordered, schemas };
}

function localDefinitions(schema, descriptor) {
  const entries = Object.entries(schema.$defs ?? {}).sort(([left], [right]) => left.localeCompare(right));
  const names = new Map();
  for (const [name] of entries) {
    const typeName = typeNameFromDefinition(name);
    const previous = names.get(typeName);
    if (previous && previous !== name) {
      throw new Error(`contract.generator-name-collision: ${descriptor.schemaRelativePath} definitions ${previous}, ${name}`);
    }
    names.set(typeName, name);
  }
  return { entries, names };
}

function externalOfficeReference(reference) {
  const hash = reference.indexOf("#");
  const source = hash === -1 ? reference : reference.slice(0, hash);
  return source.startsWith("https://affiliate-operations.example/schemas/office-v2/");
}

function descriptorForSource(source, currentDescriptor, descriptors) {
  if (source === "" || source === currentDescriptor.schemaId) return currentDescriptor;
  const byId = descriptors.find((descriptor) => descriptor.schemaId === source);
  if (byId) return byId;
  const base = currentDescriptor.schemaRelativePath.slice(0, currentDescriptor.schemaRelativePath.lastIndexOf("/") + 1);
  const normalized = `${base}${source}`.replaceAll("\\", "/");
  const byPath = descriptors.find((descriptor) => descriptor.schemaRelativePath === normalized);
  if (byPath) return byPath;
  throw new Error(`contract.generator-reference-missing: external schema ${source}`);
}

function resolveReference(reference, currentDescriptor, descriptors, schemas) {
  if (typeof reference !== "string") throw new Error("contract.generator-reference-invalid: $ref must be a string");
  const hash = reference.indexOf("#");
  const source = hash === -1 ? reference : reference.slice(0, hash);
  const fragment = hash === -1 ? "" : reference.slice(hash);
  if (source && !externalOfficeReference(reference) && !source.startsWith("#")) {
    throw new Error(`contract.generator-unsupported-schema: external reference ${reference}`);
  }
  if (fragment !== "#/$defs/" + fragment.slice("#/$defs/".length)) {
    throw new Error(`contract.generator-reference-invalid: ${reference}`);
  }
  const match = /^#\/\$defs\/([^/]+)$/u.exec(fragment);
  if (!match) throw new Error(`contract.generator-reference-invalid: ${reference}`);
  const descriptor = descriptorForSource(source, currentDescriptor, descriptors);
  const loaded = schemas.get(descriptor.schemaId);
  if (!loaded?.schema.$defs || !Object.hasOwn(loaded.schema.$defs, match[1])) {
    throw new Error(`contract.generator-reference-missing: ${reference}`);
  }
  return { descriptor, name: match[1], typeName: typeNameFromDefinition(match[1]) };
}

function collectReferences(node, callback) {
  if (Array.isArray(node)) {
    for (const entry of node) collectReferences(entry, callback);
    return;
  }
  if (!node || typeof node !== "object") return;
  if (Object.hasOwn(node, "$ref")) callback(node.$ref);
  for (const [key, value] of Object.entries(node)) {
    if (key !== "$ref") collectReferences(value, callback);
  }
}

function assertAcyclic(ordered, schemas) {
  const graph = new Map();
  for (const descriptor of ordered) {
    const schema = schemas.get(descriptor.schemaId).schema;
    for (const name of Object.keys(schema.$defs ?? {})) {
      const key = `${descriptor.schemaId}#/$defs/${name}`;
      const edges = [];
      collectReferences(schema.$defs[name], (reference) => {
        const target = resolveReference(reference, descriptor, ordered, schemas);
        edges.push(`${target.descriptor.schemaId}#/$defs/${target.name}`);
      });
      graph.set(key, edges.toSorted());
    }
  }
  const visiting = new Set();
  const visited = new Set();
  const walk = (key, path) => {
    if (visiting.has(key)) {
      throw new Error(`contract.generator-cycle: ${[...path, key].join(" -> ")}`);
    }
    if (visited.has(key)) return;
    visiting.add(key);
    for (const edge of graph.get(key) ?? []) walk(edge, [...path, key]);
    visiting.delete(key);
    visited.add(key);
  };
  for (const key of graph.keys()) walk(key, []);
}

function moduleSpecifier(fromGeneratedPath, targetGeneratedPath) {
  let value = relative(dirname(fromGeneratedPath), targetGeneratedPath).replaceAll("\\", "/").replace(/\.ts$/u, ".js");
  if (!value.startsWith(".")) value = `./${value}`;
  return value;
}

function typeForSchema(schema, context) {
  if (schema.$ref) {
    const target = resolveReference(schema.$ref, context.descriptor, context.descriptors, context.schemas);
    if (target.descriptor.schemaId === context.descriptor.schemaId) return target.typeName;
    const alias = `${typeNameFromDefinition(basename(target.descriptor.generatedRelativePath, ".ts"))}${target.typeName}`;
    const existing = context.imports.get(alias);
    const specifier = moduleSpecifier(context.descriptor.generatedRelativePath, target.descriptor.generatedRelativePath);
    if (existing && (existing.exportName !== target.typeName || existing.specifier !== specifier)) {
      throw new Error(`contract.generator-name-collision: imported type ${alias}`);
    }
    if (context.localNames.has(alias)) throw new Error(`contract.generator-name-collision: imported type ${alias}`);
    context.imports.set(alias, { exportName: target.typeName, specifier });
    return alias;
  }
  if (Object.hasOwn(schema, "const")) return literal(schema.const);
  if (schema.enum) return union(schema.enum.map(literal));
  if (schema.oneOf) return union(schema.oneOf.map((entry) => typeForSchema(entry, context)));
  if (schema.anyOf) return union(schema.anyOf.map((entry) => typeForSchema(entry, context)));
  if (schema.allOf || schema.not || schema.if || schema.then || schema.else) {
    throw new Error("contract.generator-unsupported-schema: conditional or intersection keyword");
  }
  if (schema.type === "string") return "string";
  if (schema.type === "integer" || schema.type === "number") return "number";
  if (schema.type === "boolean") return "boolean";
  if (schema.type === "null") return "null";
  if (schema.type === "array") {
    if (!schema.items) throw new Error("contract.generator-unsupported-schema: array without items");
    return `ReadonlyArray<${typeForSchema(schema.items, context)}>`;
  }
  if (schema.type === "object") {
    if (schema.additionalProperties === true) {
      throw new Error("contract.generator-unsupported-schema: open object");
    }
    const required = new Set(schema.required ?? []);
    const properties = Object.entries(schema.properties ?? {})
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([name, property]) => (
        `  readonly ${propertyName(name)}${required.has(name) ? "" : "?"}: ${typeForSchema(property, context)};`
      ));
    return `{
${properties.join("\n")}
}`;
  }
  throw new Error(`contract.generator-unsupported-schema: unsupported schema node ${JSON.stringify(schema)}`);
}

function renderDefinition(name, schema, context) {
  const typeName = typeNameFromDefinition(name);
  const type = typeForSchema(schema, context);
  const branded = shouldBrand(typeName) ? ` & Brand<${literal(typeName)}>` : "";
  return `export type ${typeName} = ${type}${branded};`;
}

export function generateSchemaSource(root, descriptor, descriptors = officeV2SchemaDescriptors) {
  const { ordered, schemas } = readSchemas(root, descriptors);
  assertAcyclic(ordered, schemas);
  const loaded = schemas.get(descriptor.schemaId);
  if (!loaded) throw new Error(`contract.generator-descriptor-missing: ${descriptor.schemaId}`);
  const { entries, names } = localDefinitions(loaded.schema, descriptor);
  const context = { descriptor, descriptors: ordered, schemas, imports: new Map(), localNames: new Set(names.keys()) };
  const definitions = entries.map(([name, definition]) => renderDefinition(name, definition, context));
  const imports = [...context.imports.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([alias, { exportName, specifier }]) => `import type { ${exportName} as ${alias} } from ${literal(specifier)};`);
  const schemaHash = createHash("sha256").update(loaded.bytes).digest("hex");
  return [
    generatedTypeHeader,
    `// Source schema: ${descriptor.schemaRelativePath}`,
    `// Source schema SHA-256: ${schemaHash}`,
    "",
    ...imports,
    ...(imports.length ? [""] : []),
    "declare const officeV2Brand: unique symbol;",
    "type Brand<Name extends string> = { readonly [officeV2Brand]: Name };",
    "",
    ...definitions,
    "",
  ].join("\n");
}

export function generateCommonV2Source(root = repositoryRoot) {
  return generateSchemaSource(root, commonDescriptor, officeV2SchemaDescriptors);
}

export function expectedGeneratedFiles(root = repositoryRoot, descriptors = officeV2SchemaDescriptors) {
  return new Map(validateSchemaDescriptors(descriptors).map((descriptor) => [
    descriptor.generatedRelativePath,
    generateSchemaSource(root, descriptor, descriptors),
  ]));
}

function collectGeneratedFiles(directory) {
  if (!existsSync(directory)) return [];
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = join(directory, entry.name);
    return entry.isDirectory() ? collectGeneratedFiles(path) : entry.name.endsWith(".ts") ? [path] : [];
  });
}

export function checkGeneratedFiles(root = repositoryRoot, descriptors = officeV2SchemaDescriptors) {
  const expected = expectedGeneratedFiles(root, descriptors);
  const generatedRoot = join(root, "packages/office-v2-contracts/src/generated");
  const actualFiles = collectGeneratedFiles(generatedRoot)
    .map((path) => relative(root, path).replaceAll("\\", "/"))
    .sort();
  const unexpected = actualFiles.filter((path) => !expected.has(path));
  if (unexpected.length > 0) {
    throw new Error(`contract.generated-drift: unexpected generated files ${unexpected.join(", ")}`);
  }
  for (const [path, content] of expected) {
    const absolutePath = join(root, path);
    if (!existsSync(absolutePath)) {
      throw new Error(`contract.generated-drift: missing ${path}`);
    }
    const actual = readFileSync(absolutePath, "utf8");
    if (actual !== content) {
      throw new Error(`contract.generated-drift: generated bytes differ for ${path}`);
    }
  }
  return "Office V2 generated contracts are deterministic and drift-free.";
}

export function writeGeneratedFiles(root = repositoryRoot, descriptors = officeV2SchemaDescriptors) {
  for (const [path, content] of expectedGeneratedFiles(root, descriptors)) {
    const absolutePath = join(root, path);
    mkdirSync(dirname(absolutePath), { recursive: true });
    writeFileSync(absolutePath, content);
  }
  return "Office V2 generated contracts written.";
}

function main() {
  const mode = process.argv[2];
  if (mode === "--write") {
    console.log(writeGeneratedFiles());
  } else if (mode === "--check") {
    console.log(checkGeneratedFiles());
  } else {
    throw new Error("Usage: node scripts/office-v2-contracts-generate.mjs --write|--check");
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  try {
    main();
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
